def reachingPoints(sx: int, sy: int, tx: int, ty: int) -> bool:
    while tx >= sx and ty >= sy:
        if tx == sx:
            return ty == sy
        if ty == sy:
            return tx == sx
        if tx > ty:
            if (tx - sx) % ty == 0:
                return True
            tx %= ty
        else:
            if (ty - sy) % tx == 0:
                return True
            ty %= tx
    return False
